"""Season, weather and clothing companion."""
from english.u16.content import CORE, MEANINGS, SEASONS, WEATHER, picture
from english.study.author import word as w, question as q, choice as c, dialogue as d
from english.study.render import render_study as render

def data():
    words = [w('seasons', s, v, 'It is ' + s + '.') for s, v in zip(SEASONS, ['mùa xuân', 'mùa hè', 'mùa thu', 'mùa đông'])]
    words += [w('clothes', k, v, 'I wear ' + k + '.', image=k) for k, v in zip(CORE, MEANINGS)]
    words += [w('weather', k, v, 'The weather is ' + k + '.') for k, v in [('warm', 'ấm'), ('hot', 'nóng'), ('cool', 'mát'), ('cold', 'lạnh'), ('sunny', 'có nắng'), ('rainy', 'có mưa'), ('cloudy', 'có mây'), ('dry', 'khô'), ('humid', 'ẩm'), ('windy', 'có gió'), ('snowy', 'có tuyết')]]
    words += [w('weather', 'dry season', 'mùa khô', 'There is a dry season in the south of Viet Nam.')]
    dialogs = [d('seasons', 'Hỏi mùa', 'What season is it?', 'It is spring.', 'Không suy mùa từ tháng nếu không biết địa điểm.'), d('seasons', 'Mùa thu', 'Is it autumn?', 'Yes, it is.', 'Câu hỏi Yes/No thường lên giọng.'), d('clothes', 'Quần áo mùa đông', 'What do you usually wear in winter?', 'I wear a jumper.', 'Đây là lựa chọn của người nói, không phải quy tắc cho mọi người.'), d('clothes', 'Quần áo mùa hè', 'What do you usually wear in summer?', 'I wear trousers.', 'Trousers và jeans số nhiều, không dùng a.'), d('weather', 'Hỏi thời tiết', 'How is the weather in Ha Noi in spring?', 'It is warm and rainy.', 'Thông tin trong thẻ bài tập; không phải dự báo.'), d('weather', 'Đọc câu trọn ý', 'How is the weather in autumn?', 'It is cool and cloudy.', 'Câu kể trong Lesson 3 xuống giọng cuối câu; ABC chỉ là tên chữ cái.')]
    exercises = [c('season-listen', 'seasons', 'Which season is named?', 'winter', 'Nghe winter.', SEASONS, speech='It is winter.'), q('season-word', 'seasons', 'Complete: sum___. Write the whole season.', 'summer', 'Summer.'), q('season-in', 'seasons', 'It is warm ___ spring.', 'in', 'In + mùa.'), q('season-full', 'seasons', 'Rewrite in full: It’s spring.', 'It is spring.', 'It is.'), c('clothes-listen', 'clothes', 'Which clothes are named?', 'jeans', 'Nghe jeans.', CORE, speech='I wear jeans.'), q('clothes-base', 'clothes', 'What do you usually ___ in winter? Use wear.', 'wear', 'Do + wear, không wears.'), q('clothes-a', 'clothes', 'I wear ___ jumper.', 'a', 'A jumper.'), q('clothes-sentence', 'clothes', 'Card: I / wear / trousers. Write one sentence in this order.', 'I wear trousers.', 'Không thêm a trước trousers.'), c('weather-listen', 'weather', 'Which weather phrase is named?', 'hot and sunny', 'Nghe hot and sunny.', WEATHER, speech='It is hot and sunny.'), q('weather-is', 'weather', 'It ___ cold and dry.', 'is', 'It is.'), q('weather-and', 'weather', 'It is warm ___ rainy.', 'and', 'And.'), q('weather-sentence', 'weather', 'Card: cool and cloudy. Write one full-form sentence starting with It.', 'It is cool and cloudy.', 'It is + hai tính từ.')]
    return dict(unit=16, key='mia5:learn:en-u16-v1', intro='Học mùa, thời tiết và trang phục: nghe, nghe chậm, ABC và hội thoại theo thẻ.', groups=[dict(id='seasons', name='Các mùa', tip='Spring, summer, autumn, winter; in + mùa. Phần đọc có dry season/rainy season ở miền Nam, không ép mọi nơi có bốn mùa.'), dict(id='clothes', name='Em thường mặc gì?', tip='What do you usually wear in…? I wear… A blouse / a jumper, nhưng trousers / jeans không có a. Trang phục là lựa chọn trong thẻ.'), dict(id='weather', name='Thời tiết và nhịp câu', tip='How’s = How is the weather…? It is + tính từ. Câu kể xuống giọng ở cuối. Thẻ là giả định, không phải khí hậu cố định của thành phố. ABC là tên chữ cái, không phải phonics.')], words=words, dialogues=dialogs, exercises=exercises)

def render_study():
    return render(data(), picture)
